<?php
require_once __DIR__ . '/../../includes/auth.php'; require_role('admin');
$userId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); if (!$userId || $userId < 1) { flash_set('error', 'Invalid user ID specified.'); redirect('modules/users/index.php'); }
try { $stmt = $conn->prepare('SELECT user_id, username, email, full_name, role, is_active, last_login_at, created_at, updated_at FROM users WHERE user_id = ? LIMIT 1'); if (!$stmt) throw new RuntimeException($conn->error); $stmt->bind_param('i', $userId); $stmt->execute(); $user = $stmt->get_result()->fetch_assoc(); $stmt->close(); if (!$user) { flash_set('error', 'User record not found.'); redirect('modules/users/index.php'); } } catch (Throwable $e) { error_log('Database exception loading user: ' . $e->getMessage()); flash_set('error', 'A database error occurred while retrieving the user.'); redirect('modules/users/index.php'); }
$pageTitle = 'User: ' . $user['full_name']; $currentNav = 'users'; include __DIR__ . '/../../includes/header.php'; include __DIR__ . '/../../includes/sidebar.php';
?>
<div class="page-header"><div class="page-title-group"><h1>User Profile</h1><div class="page-subtitle">User ID #<?= (int) $user['user_id'] ?> &bull; <?= e($user['full_name']) ?></div></div><div class="page-actions"><a href="<?= e(url('modules/users/index.php')) ?>" class="btn btn-secondary">Back to User List</a><a href="<?= e(url('modules/users/edit.php?id=' . (int) $user['user_id'])) ?>" class="btn btn-primary">Edit User</a></div></div>
<div class="card card-medium"><div class="card-header"><h2><?= e($user['full_name']) ?></h2><?php if ((int)$user['is_active'] === 1): ?><span class="badge badge-success">Active</span><?php else: ?><span class="badge badge-danger">Inactive</span><?php endif; ?></div><div class="card-body"><div class="table-responsive"><table class="table"><tbody>
<?php foreach ([['User ID', '#' . (int)$user['user_id']],['Full Name',$user['full_name']],['Username',$user['username']],['Email',$user['email']],['Role',ucwords(str_replace('_',' ',$user['role']))],['Last Login',$user['last_login_at'] ?: 'Never'],['Created',$user['created_at']],['Last Updated',$user['updated_at']]] as [$label,$value]): ?><tr><th style="width: 220px;"><?= e($label) ?></th><td><?= e($value) ?></td></tr><?php endforeach; ?><tr><th>Status</th><td><?php if ((int)$user['is_active'] === 1): ?><span class="badge badge-success">Active</span><?php else: ?><span class="badge badge-danger">Inactive</span><?php endif; ?></td></tr>
</tbody></table></div></div></div>
<?php include __DIR__ . '/../../includes/footer.php'; ?>